SELECT '1. 兩張表存在且已啟用 RLS' AS item, (SELECT count(*) FROM pg_class c WHERE c.oid IN (to_regclass('public.teamcommission_venue_bonus_flags'), to_regclass('public.teamcommission_venue_revenue_source_overrides')) AND c.relrowsecurity) = 2 AS ok
UNION ALL SELECT '2. 旅行日館別全數帶入（exclude＝true、群組＝旅行日系列），且沒有其他館', (SELECT count(*) FROM public.teamcommission_venue_bonus_flags f JOIN public.accommodation_info a ON a.id = f.accommodation_id WHERE a.name LIKE '旅行日%' AND f.exclude_from_commission AND f.fixed_merge_group = '旅行日系列') = (SELECT count(*) FROM public.accommodation_info WHERE name LIKE '旅行日%') AND (SELECT count(*) FROM public.teamcommission_venue_bonus_flags) = (SELECT count(*) FROM public.accommodation_info WHERE name LIKE '旅行日%')
UNION ALL SELECT '3. 單館來源覆蓋表為空（全站設定不變）', (SELECT count(*) FROM public.teamcommission_venue_revenue_source_overrides) = 0
UNION ALL SELECT '4. anon 無任何權限；authenticated 有 SELECT／INSERT／UPDATE／DELETE；service_role 可讀寫', NOT has_table_privilege('anon', 'public.teamcommission_venue_bonus_flags', 'SELECT') AND NOT has_table_privilege('anon', 'public.teamcommission_venue_revenue_source_overrides', 'SELECT') AND has_table_privilege('authenticated', 'public.teamcommission_venue_bonus_flags', 'UPDATE') AND has_table_privilege('authenticated', 'public.teamcommission_venue_revenue_source_overrides', 'INSERT') AND has_table_privilege('service_role', 'public.teamcommission_venue_bonus_flags', 'SELECT') AND has_table_privilege('service_role', 'public.teamcommission_venue_revenue_source_overrides', 'SELECT')
UNION ALL SELECT '5. 政策數：flags 2、overrides 4', (SELECT count(*) FROM pg_policy WHERE polrelid = 'public.teamcommission_venue_bonus_flags'::regclass) = 2 AND (SELECT count(*) FROM pg_policy WHERE polrelid = 'public.teamcommission_venue_revenue_source_overrides'::regclass) = 4;

SELECT a.name, f.exclude_from_commission, f.fixed_merge_group FROM public.teamcommission_venue_bonus_flags f JOIN public.accommodation_info a ON a.id = f.accommodation_id ORDER BY a.name;
